var MIN_SEARCH_QUERY_LENGTH = 3;

// server/routes/search.ts
var route7 = new Hono2();
route7.get("/api/search", requireAuth, async (c) => {
  try {
    const { userId } = getAuthenticatedAuth(c);
    const url = new URL(c.req.url);
    const query2 = url.searchParams.get("q");
    const type2 = url.searchParams.get("type") || "all";
    const limit = parseInt(url.searchParams.get("limit") || "50");
    const threadIdParam = url.searchParams.get("threadId")?.trim() || null;
    const spaceIdParam = url.searchParams.get("spaceId")?.trim() || null;
    const excludeLegacyScripture = url.searchParams.get("excludeLegacyScripture") === "1" || url.searchParams.get("excludeLegacyScripture") === "true";
    if (!query2 || query2.trim().length === 0) {
      return c.json({ results: [] });
    }
    const trimmedQuery = query2.trim();
    if (trimmedQuery.length < MIN_SEARCH_QUERY_LENGTH) {
      return c.json({ results: [], query: query2, type: type2, total: 0 });
    }
    const searchNotes = type2 === "all" || type2 === "notes";
    const searchThreads = (type2 === "all" || type2 === "threads") && !threadIdParam;
    const noteScopeFilters = threadIdParam ? [eq(Notes.threadId, threadIdParam)] : spaceIdParam ? [eq(Notes.spaceId, spaceIdParam)] : [];
    if (excludeLegacyScripture) {
      noteScopeFilters.push(ne(Notes.noteType, "scripture"));
    }
    const threadScopeFilters = spaceIdParam && !threadIdParam ? [eq(Threads.spaceId, spaceIdParam)] : [];
    const useFTS = trimmedQuery.length >= MIN_SEARCH_QUERY_LENGTH;
    const ftsSubstringPattern = useFTS ? `%${trimmedQuery}%` : "";
    let notesRows = [];
    let threadsRows = [];
    if (searchNotes) {
      const scriptureTranslationSql = sql`(
        SELECT ${ScriptureMetadata.translation}
        FROM ${ScriptureMetadata}
        WHERE ${ScriptureMetadata.noteId} = ${Notes.id}
        LIMIT 1
      )`;
      if (useFTS) {
        const tsQuery = sql`plainto_tsquery('english', ${trimmedQuery})`;
        const noteTsVector = sql`to_tsvector('english', COALESCE(${Notes.title}, '') || ' ' || ${Notes.content} || ' ' || COALESCE(${scriptureTranslationSql}, ''))`;
        notesRows = await db.select({
          id: Notes.id,
          title: Notes.title,
          content: Notes.content,
          noteType: Notes.noteType,
          scriptureTranslation: scriptureTranslationSql,
          threadId: Notes.threadId,
          spaceId: Notes.spaceId,
          createdAt: Notes.createdAt,
          updatedAt: Notes.updatedAt,
          primaryCollection: Notes.primaryCollection,
          secondaryCollections: Notes.secondaryCollections
        }).from(Notes).where(
          and(
            eq(Notes.userId, userId),
            not(eq(Notes.contentEncrypted, true)),
            ...noteScopeFilters,
            or(
              sql`${noteTsVector} @@ ${tsQuery}`,
              like(Notes.title, ftsSubstringPattern),
              like(Notes.content, ftsSubstringPattern),
              sql`COALESCE(${scriptureTranslationSql}, '') ILIKE ${ftsSubstringPattern}`
            )
          )
        ).orderBy(
          sql`CASE WHEN ${noteTsVector} @@ ${tsQuery} THEN ts_rank(${noteTsVector}, ${tsQuery}) ELSE -1::real END DESC`,
          desc(Notes.updatedAt)
        ).limit(limit);
      } else {
        const searchTerm = `%${trimmedQuery}%`;
        notesRows = await db.select({
          id: Notes.id,
          title: Notes.title,
          content: Notes.content,
          noteType: Notes.noteType,
          scriptureTranslation: scriptureTranslationSql,
          threadId: Notes.threadId,
          spaceId: Notes.spaceId,
          createdAt: Notes.createdAt,
          updatedAt: Notes.updatedAt,
          primaryCollection: Notes.primaryCollection,
          secondaryCollections: Notes.secondaryCollections
        }).from(Notes).where(
          and(
            eq(Notes.userId, userId),
            not(eq(Notes.contentEncrypted, true)),
            ...noteScopeFilters,
            or(
              like(Notes.title, searchTerm),
              like(Notes.content, searchTerm),
              sql`COALESCE(${scriptureTranslationSql}, '') ILIKE ${searchTerm}`
            )
          )
        ).orderBy(desc(Notes.updatedAt), desc(Notes.createdAt), Notes.id).limit(limit);
      }
    }
    if (searchThreads) {
      if (useFTS) {
        const tsQuery = sql`plainto_tsquery('english', ${trimmedQuery})`;
        const threadTsVector = sql`to_tsvector('english', ${Threads.title})`;
        threadsRows = await db.select({
          id: Threads.id,
          title: Threads.title,
          subtitle: Threads.subtitle,
          spaceId: Threads.spaceId,
          color: Threads.color,
          createdAt: Threads.createdAt,
          updatedAt: Threads.updatedAt
        }).from(Threads).where(
          and(
            eq(Threads.userId, userId),
            ...threadScopeFilters,
            or(
              sql`${threadTsVector} @@ ${tsQuery}`,
              like(Threads.title, ftsSubstringPattern),
              sql`COALESCE(${Threads.subtitle}, '') ILIKE ${ftsSubstringPattern}`
            )
          )
        ).orderBy(
          sql`CASE WHEN ${threadTsVector} @@ ${tsQuery} THEN ts_rank(${threadTsVector}, ${tsQuery}) ELSE -1::real END DESC`,
          desc(Threads.updatedAt)
        ).limit(limit);
      } else {
        const searchTerm = `%${trimmedQuery}%`;
        threadsRows = await db.select({
          id: Threads.id,
          title: Threads.title,
          subtitle: Threads.subtitle,
          spaceId: Threads.spaceId,
          color: Threads.color,
          createdAt: Threads.createdAt,
          updatedAt: Threads.updatedAt
        }).from(Threads).where(
          and(
            eq(Threads.userId, userId),
            ...threadScopeFilters,
            like(Threads.title, searchTerm)
          )
        ).orderBy(desc(Threads.updatedAt), desc(Threads.createdAt), Threads.id).limit(limit);
      }
    }
    const noteIdsForColors = notesRows.map((n) => n.id);
    const threadColorsMap = await getThreadColorsForNotesBatch(noteIdsForColors, userId);
    const noteResults = notesRows.map((note) => {
      const resolvedNoteType = note.noteType || "default";
      const normalizedScriptureTranslation = note.scriptureTranslation?.trim() || null;
      const scriptureTranslationForResult = resolvedNoteType === "scripture" ? normalizedScriptureTranslation || "NET" : null;
      const threadColors = threadColorsMap.get(note.id);
      return {
        id: note.id,
        type: "note",
        title: note.title || "Untitled Note",
        // Keep full note content so CardNote preview behavior matches other lists (e.g. dashboard).
        content: note.content,
        contentEncrypted: false,
        noteType: resolvedNoteType,
        version: scriptureTranslationForResult,
        scriptureTranslation: scriptureTranslationForResult,
        threadId: note.threadId,
        spaceId: note.spaceId,
        lastUpdated: note.updatedAt || note.createdAt,
        createdAt: note.createdAt,
        updatedAt: note.updatedAt,
        threadColors: threadColors && threadColors.length > 0 ? threadColors : void 0,
        primaryCollection: note.primaryCollection ?? null,
        secondaryCollections: parseNoteSecondaryCollections(note.secondaryCollections)
      };
    });
    const threadResults = threadsRows.map((thread) => ({
      id: thread.id,
      type: "thread",
      title: thread.title,
      subtitle: thread.subtitle || "",
      spaceId: thread.spaceId,
      color: thread.color,
      lastUpdated: thread.updatedAt || thread.createdAt,
      createdAt: thread.createdAt,
      updatedAt: thread.updatedAt
    }));
    let results = [...noteResults, ...threadResults];
    if (!useFTS) {
      results.sort(
        (a, b3) => new Date(String(b3.lastUpdated)).getTime() - new Date(String(a.lastUpdated)).getTime()
      );
    }
    results = results.slice(0, limit);
    return c.json({ results, query: query2, type: type2, total: results.length });
  } catch (error) {
    const standardError = handleAPIError(error, {
      endpoint: "/api/search",
      action: "search"
    });
    return c.json({ error: standardError.message, code: standardError.code }, 500);
  }
});
var search_default = route7;

// server/routes/content.ts
var route8 = new Hono2();
route8.get("/api/content/load-more", async (c) => {
  try {
    const auth = getAuth(c);
    if (!auth.userId) {
      console.log("[api/content/load-more] No auth userId \u2014 returning 401");
      return c.json({ error: "Authentication required" }, 401);
    }
    console.log("[api/content/load-more] auth.userId", auth.userId);
    await getCachedUserData(auth.userId);
    const offset = parseInt(c.req.query("offset") || "0", 10);
    const limit = parseInt(c.req.query("limit") || "20", 10);
    const filter2 = c.req.query("filter") || "all";
    if (filter2 === "scripture") {
      return c.json({ items: [], hasMore: false, offset, limit });
    }
    const fetchLimit = filter2 === "all" ? limit : limit * 3;
    const filterExcludeReferencedScripture = filter2 === "all";
    const needReferencedScripture = filter2 === "all" && offset === 0;
    const [items, referencedScriptureNotes] = needReferencedScripture ? await Promise.all([
      getContentItems(auth.userId, fetchLimit, offset, filterExcludeReferencedScripture),
      getReferencedScriptureNotesWithoutLastVisited(auth.userId)
    ]) : [await getContentItems(auth.userId, fetchLimit, offset, filterExcludeReferencedScripture), []];
    let filteredItems = items;
    if (filter2 === "threads") {
      filteredItems = items.filter((item) => item.type === "thread");
    } else if (filter2 === "notes") {
      filteredItems = items.filter((item) => item.type === "note" && (item.noteType === "default" || !item.noteType));
    } else if (filter2 === "resources") {
      filteredItems = items.filter((item) => item.type === "note" && item.noteType === "resource");
    }
    const limitedItems = filteredItems.slice(0, limit);
    const hasMore = limitedItems.length === limit && (items.length === fetchLimit || filteredItems.length > limit);
    console.log("[api/content/load-more] items count", { returned: limitedItems.length, rawCount: items.length, filter: filter2, offset, limit });
    return c.json({
      items: limitedItems,
      hasMore,
      offset,
      limit,
      referencedScriptureNotes: needReferencedScripture ? referencedScriptureNotes : void 0
    });
  } catch (error) {
    try {
      const err = error instanceof Error ? error : new Error(String(error));
      console.error("[api/content/load-more] Error:", err.message, err.stack);
      const body = {
        error: "Failed to load more content",
        details: err.message,
        hint: err.stack?.split("\n").slice(0, 3).join(" | ") ?? ""
      };
      return c.json(body, 500, { "Content-Type": "application/json" });
    } catch (fallbackErr) {
      console.error("[api/content/load-more] Fallback error:", fallbackErr);
      return c.json(
        { error: "Failed to load more content", details: String(fallbackErr) },
        500,
        { "Content-Type": "application/json" }
      );
    }
  }
});
