route10.post("/api/notes/:noteId/share", requireAuth, rateLimit("write"), async (c) => {
  try {
    const auth = getAuthenticatedAuth(c);
    const noteId = requireParam(c, "noteId");
    const { action } = await c.req.json();
    if (!action || !["enable", "disable", "refresh"].includes(action)) return c.json({ error: "Invalid action" }, 400);
    const note = first(
      await db.select({
        id: Notes.id,
        threadId: Notes.threadId,
        addedBy: Notes.addedBy,
        isPublic: Notes.isPublic,
        shareToken: Notes.shareToken,
        userId: Notes.userId,
        contentEncrypted: Notes.contentEncrypted
      }).from(Notes).where(eq(Notes.id, noteId)).limit(1)
    );
    if (!note) return c.json({ error: "Note not found" }, 404);
    if (note.userId !== auth.userId) return c.json({ error: "You do not have permission" }, 403);
    if (isOnboardingSystemNote(note)) return c.json({ error: "This note cannot be shared.", code: "ONBOARDING_NOTE_READ_ONLY" }, 400);
    if (note.contentEncrypted && (action === "enable" || action === "refresh")) {
      return c.json({ error: "Remove the lock first to share it.", code: "ENCRYPTED_NOTE_CANNOT_SHARE" }, 400);
    }
    const now2 = nowISO();
    let newShareToken = null;
    let isPublic = note.isPublic;
    if (action === "enable") {
      newShareToken = generateShareToken();
      isPublic = true;
      await db.update(Notes).set({ isPublic: true, shareToken: newShareToken, shareTokenCreatedAt: now2, updatedAt: now2 }).where(and(eq(Notes.id, noteId), eq(Notes.userId, auth.userId)));
    } else if (action === "disable") {
      newShareToken = null;
      isPublic = false;
      await db.update(Notes).set({ isPublic: false, shareToken: null, shareTokenCreatedAt: null, updatedAt: now2 }).where(and(eq(Notes.id, noteId), eq(Notes.userId, auth.userId)));
    } else if (action === "refresh") {
      if (!note.isPublic) return c.json({ error: "Cannot refresh share link for a private note" }, 400);
      newShareToken = generateShareToken();
      isPublic = true;
      await db.update(Notes).set({ shareToken: newShareToken, shareTokenCreatedAt: now2, updatedAt: now2 }).where(and(eq(Notes.id, noteId), eq(Notes.userId, auth.userId)));
    }
    const origin = new URL(c.req.url).origin;
    const shareUrl = newShareToken ? `${origin}/shared/note/${newShareToken}` : null;
    return c.json({ success: true, isPublic, shareToken: newShareToken, shareUrl, shareTokenCreatedAt: action !== "disable" ? now2 : null });
  } catch (error) {
    const standardError = handleAPIError(error, { endpoint: "/api/notes/[noteId]/share", action: "update_share_status", noteId: c.req.param("noteId") });
    return c.json({ error: standardError.message, code: standardError.code }, 500);
  }
});
