app11.post("/api/admin/backfill-auto-tags", async (c) => {
  const gate = requireHarvousAdmin(c);
  if (gate) return gate;
  try {
    const systemUserId = getHarvousSystemUserId();
    const body = await c.req.json().catch(() => ({}));
    const dryRun = body.dryRun === true;
    const minConfidence = typeof body.minConfidence === "number" && body.minConfidence >= 0 && body.minConfidence <= 1 ? body.minConfidence : AUTO_TAG_CONFIDENCE_SYSTEM_AUTOGEN;
    const onlyWithoutTags = body.onlyWithoutTags !== false;
    const noteIdsFilter = Array.isArray(body.noteIds) ? body.noteIds.filter((id) => typeof id === "string" && id.length > 0) : null;
    const allNotes = await db.select({
      id: Notes.id,
      title: Notes.title,
      content: Notes.content,
      contentEncrypted: Notes.contentEncrypted
    }).from(Notes).where(eq(Notes.userId, systemUserId));
    let candidates = allNotes.filter((n) => !n.contentEncrypted);
    if (noteIdsFilter && noteIdsFilter.length > 0) {
      const idSet = new Set(noteIdsFilter);
      candidates = candidates.filter((n) => idSet.has(n.id));
    }
    if (onlyWithoutTags) {
      const taggedRows = await db.select({ noteId: NoteTags.noteId }).from(NoteTags).innerJoin(Notes, eq(Notes.id, NoteTags.noteId)).where(eq(Notes.userId, systemUserId));
      const taggedSet = new Set(taggedRows.map((r) => r.noteId));
      candidates = candidates.filter((n) => !taggedSet.has(n.id));
    }
    const details = [];
    let notesWithSuggestions = 0;
    let totalApplied = 0;
    for (const note of candidates) {
      const result = await generateAutoTags(note.title || "", note.content || "", systemUserId, minConfidence);
      const keywords = result.suggestions.map((s2) => s2.keyword);
      if (result.suggestions.length === 0) {
        details.push({
          noteId: note.id,
          title: note.title ?? null,
          suggestionCount: 0,
          keywords: [],
          applied: 0
        });
        continue;
      }
      notesWithSuggestions++;
      if (dryRun) {
        details.push({
          noteId: note.id,
          title: note.title ?? null,
          suggestionCount: result.suggestions.length,
          keywords,
          applied: 0
        });
        continue;
      }
      const { applied } = await applyAutoTags(note.id, result.suggestions, systemUserId);
      totalApplied += applied;
      details.push({
        noteId: note.id,
        title: note.title ?? null,
        suggestionCount: result.suggestions.length,
        keywords,
        applied
      });
    }
    return c.json({
      success: true,
      dryRun,
      minConfidence,
      onlyWithoutTags,
      candidateCount: candidates.length,
      notesWithSuggestions,
      totalApplied: dryRun ? 0 : totalApplied,
      details
    });
  } catch (error) {
    console.error("[admin backfill-auto-tags]", error);
    return c.json(
      { success: false, error: error instanceof Error ? error.message : String(error) },
      500
    );
  }
});
